import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第六百三十六章 入住旅店、客栈的比喻","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/636第六百三十六章 入住旅店、客栈的比喻-五取蕴.md","filePath":"meditation/巴利文大藏经/636第六百三十六章 入住旅店、客栈的比喻-五取蕴.md"}'),o={name:"meditation/巴利文大藏经/636第六百三十六章 入住旅店、客栈的比喻-五取蕴.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第六百三十六章-入住旅店、客栈的比喻" tabindex="-1">第六百三十六章 入住旅店、客栈的比喻 <a class="header-anchor" href="#第六百三十六章-入住旅店、客栈的比喻" aria-label="Permalink to &quot;第六百三十六章 入住旅店、客栈的比喻&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部45相应159经/来客经(道相应/大篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“比丘们（出家人），犹如在旅店、客栈住宿，从东方、西方、北方、南方来的人投宿来到旅店、客栈会入住；国王、王族、公卿大臣投宿来到旅店、客栈会入住；婆罗门（祭司、宗教师）投宿来到旅店、客栈会入住；毘舍（平民百姓）投宿来到旅店、客栈会入住；首陀罗（奴隶）投宿来到旅店、客栈会入住。比丘们，同样的道理，修习八正道，经常修习八正道的世间人或众生（八正道解释，见第五百八十九章），他们修行的轨迹与路径几乎都是相同的，凡是能够让他们开启智慧，让他们明白和理解世间真相、真谛的正法，他们都会去修习；凡是让他们生起贪欲、渴爱、愤怒、无智愚痴等等烦恼和痛苦的法，凡是让他们沉迷、执着、挂念的法，他们都会除灭、灭尽；凡是应该亲身体验、切身体会印证各种清净境界的正法，他们都会以自己的实际行动，去实践的修行这些正法，去修习验证、核验这些正法所达到的各种清净境界；凡是能够让他们证悟解脱果位，进入涅槃境界的正法，他们都会去修习。</p><p>比丘们，什么是能够开启智慧，让世间人或众生明白和理解世间真相、真谛的法呢？五取蕴就是应该要完全明白的法。完全明白五取蕴就能开启智慧，让世间人或众生明白和理解世间的真相、真谛。什么是五取蕴呢？即是：色取蕴、受取蕴、想取蕴、行取蕴、识取蕴，由物质事物、物质身体生起的烦恼就称为「色取蕴」，由感受生起的烦恼就称为「受取蕴」，由念想生起的烦恼就称为「想取蕴」，由行为生起的烦恼就称为「行取蕴」，由认识、分别、判断生起的烦恼就称为「识取蕴」。当完全明白五取蕴的生起与灭没的时候（明白五取蕴的生起与灭没就是明白缘起法，缘起法解释，见第四十八章、第四十九章），世间人或众生就能明白和理解世间的真相、真谛。</p><p>什么是让世间人或众生生起贪欲、渴爱、愤怒、无智愚痴等等烦恼和痛苦的法呢？什么是让世间人或众生沉迷、执着、挂念的法呢？什么是世间人或众生应该除灭、灭尽的法呢？无明与有爱就是世间人或众生应该除灭、灭尽的法。什么是无明呢？就是不明白出生在世间有生命的众生都是很痛苦的，不明白痛苦的根源是贪爱，不明白要灭尽痛苦就要先灭尽贪爱，不明白要灭尽贪爱就要修习八正道（八正道解释，见第十八章），不明白苦集灭道四圣谛，没有真实的智慧，沉迷于各种欲望之中，被各种烦恼和痛苦束缚捆绑不得解脱就叫做「无明」。简单的说：无明就是无智、无知，不明白善法、正法、解脱法，没有开启智慧。</p><p>什么是有爱呢？就是对存在的贪爱，对拥有的贪爱，对生存的贪爱，对生命的贪爱。</p><p>除灭、灭尽了无明与有爱就能让世间人或众生熄灭、平息、灭尽贪欲、渴爱、愤怒、无智愚痴等等烦恼和痛苦，就能让世间人或众生不再沉迷、执着、挂念。</p><p>什么是世间人或众生应该亲身体验、切身体会印证的正法呢？什么是世间人或众生应该修习验证、核验的正法呢？「明」与「解脱」就是世间人或众生应该亲身体验、切身体会印证的正法，就是世间人或众生应该修习验证、核验的正法。</p><p>什么是明呢？就是明白出生在世间有生命的众生都是很痛苦的，明白痛苦的根源是贪爱，明白要灭尽痛苦就要先灭尽贪爱，明白要灭尽贪爱就要修习八正道（八正道解释，见第十八章），明白苦集灭道四圣谛，已经开启真实的智慧，不会再沉迷于各种欲望之中，不会再被各种烦恼和痛苦束缚捆绑就叫做「明」。简单的说：「明」就是明白善法、正法、解脱法，已经开启智慧。</p><p>什么是「解脱」呢？就是已经解除世间一切的束缚捆绑，已经灭尽一切的烦恼和痛苦，已经停止、结束生死轮回（生死轮回解释，见第五百七十八章），不会再投生到世间，已经进入没有烦恼，没有痛苦，没有执着，没有挂念，没有念想的涅槃清净境界。</p><p>「明」与「解脱」就是世间人或众生应该亲身体验、切身体会印证，修习验证、核验的正法。</p><p>什么是能够让世间人或众生证悟解脱果位，进入涅槃境界的正法呢？止与观就是能够让世间人或众生证悟解脱果位，进入涅槃境界的正法（止与观解释：见第六百一十四章）。止与观就是世间人或众生应该修习的正法。修习止与观，世间人或众生就能最终证悟解脱果位，进入清净涅槃的境界。</p><p>比丘们，世间人或众生是如何通过修习八正道，经常修习八正道来完全明白五取蕴，来除灭、灭尽无明与有爱，来体验、印证「明」与「解脱」，来完成止与观的修行的呢？世间人或众生依靠修习八正道来熄灭、平息、灭尽贪欲、渴爱、愤怒、无智愚痴、喜怒哀乐、执着、挂念等等烦恼和痛苦，他们在修习八正道的过程中就能逐渐的明白五取蕴，就能逐渐的除灭无明与有爱，就能逐渐的体验、印证「明」与「解脱」，就能逐渐的完成止与观的修行。当世间人或众生圆满的完成正见、正志、正语、正业、正命、正方便、正念、正定，这八种正道的修行，他们就能完全明白五取蕴，他们就能灭尽无明与有爱，他们就能彻底体验、印证「明」与「解脱」，他们就能圆满完成止与观的修行，最终进入没有烦恼，没有痛苦，没有执着，没有挂念，没有念想的涅槃清净境界。</p><p>比丘们，世间人或众生就是这样通过修习八正道，通过经常修习八正道来完全明白五取蕴，来除灭、灭尽无明与有爱，来体验、印证「明」与「解脱」，来完成止与观的修行的。比丘们，你们要修习八正道，你们要经常修习八正道，这样你们也能完全明白五取蕴，你们也能除灭、灭尽无明与有爱，你们也能彻底体验、印证「明」与「解脱」，你们也能圆满完成止与观的修行，你们也能最终进入没有烦恼，没有痛苦，没有执着，没有挂念，没有念想的涅槃清净境界。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',16)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
